CREATE OR REPLACE FUNCTION public.sync_billing_zero_wallet() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.total_price=0 AND (NEW.billing_only OR NEW.billing_base_amount IS NOT NULL) THEN UPDATE public.wallet_transactions SET amount=0,updated_at=now() WHERE reference_type='order_approved' AND reference_id=NEW.id; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sync_billing_zero_wallet AFTER UPDATE OF total_price ON public.projects_v3 FOR EACH ROW EXECUTE FUNCTION public.sync_billing_zero_wallet();
CREATE OR REPLACE FUNCTION public.trg_sync_location_active() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN IF OLD.billing_only THEN RETURN OLD; END IF; PERFORM public.recalc_location_active_for_hierarchy(OLD.hierarchy_project_id); RETURN OLD; END IF; IF NEW.billing_only THEN RETURN NEW; END IF; PERFORM public.recalc_location_active_for_hierarchy(NEW.hierarchy_project_id); IF TG_OP='UPDATE' AND OLD.hierarchy_project_id IS DISTINCT FROM NEW.hierarchy_project_id THEN PERFORM public.recalc_location_active_for_hierarchy(OLD.hierarchy_project_id); END IF; RETURN NEW; END; $$;